    /** Bridge length cost factor by total length L (ramps included): TTD's CalcBridgeLenCostFactor. */
    bridgeLenFactor(L) {
        let n = L, r = 0;
        if (n < 2) return 0;
        n -= 2;
        for (let i = 0; n > 0; i++) { for (let j = 0; j < i + 1 && n > 0; j++) { r += i + 1; n--; } }
        return r + 2;
    },

